// Problem Solver's after action review compares the intended result with the actual one; the
// book asks four plainer questions after the work is done, with a firm no-blame rule. The stages
// carry those four; the review's own tool stays in Problem Solver (pairsWell double_loop).
export const cbPostmortem = Object.freeze({
  ...pathTool({
    id: 'cb_postmortem',
    name: 'The Postmortem',
    when: 'A piece of work is finished and its lessons have not been captured yet.',
    failureModes: [
      'Confusing accountability with humiliation.',
      'Collecting lessons and changing nothing.',
      'Pretending every failure was secretly a success.'
    ],
    steps: [
      step('happened', 'What happened', 'What happened, as plainly as the people involved would agree?'),
      step('why', 'Why', 'Why did it happen? Look at the process and the conditions, not at who to blame.'),
      step('lessons', 'Lessons', 'What did the team learn?'),
      step('changes', 'Changes for next time', 'What will be different next time, and who owns that change?'),
      OWN_PART_STEP
    ],
    exercise: 'Hold a short review and give one improvement to a named owner.',
    pairsWell: ['double_loop', 'cb_premortem'],
    chart: {
      variant: 'stages',
      stages: [
        { id: 'happened', label: 'What happened' },
        { id: 'why', label: 'Why it happened' },
        { id: 'lessons', label: 'Lessons' },
        { id: 'changes', label: 'Changes for next time' }
      ]
    }
  }),
  variantOf: 'after_action_review'
});

